// getLogs implements lld/07 §2's get_logs, tail-limited server-side via the
// real pods/log subresource GET (PodLogOptions.TailLines), never "fetch
// everything and truncate on this side."
func (e *ToolExecutor) getLogs(ctx context.Context, rawArgs json.RawMessage) (json.RawMessage, bool, error) {
	var args getLogsArgs
	if err := json.Unmarshal(rawArgs, &args); err != nil {
		return nil, false, fmt.Errorf("invalid args: %w", err)
	}
	if args.Namespace == "" || args.Pod == "" {
		return nil, false, errors.New("namespace and pod are required")
	}

	tail := args.TailLines
	if tail <= 0 {
		tail = defaultLogTailLines
	}
	if tail > maxLogTailLines {
		tail = maxLogTailLines
	}

	opts := &corev1.PodLogOptions{
		Container: args.Container,
		Previous:  args.Previous,
		TailLines: &tail,
	}

	stream, err := e.typed.CoreV1().Pods(args.Namespace).GetLogs(args.Pod, opts).Stream(ctx)
	if err != nil {
		return nil, false, e.explainLogsError(ctx, args, err)
	}
	defer stream.Close()

	var lines []string
	scanner := bufio.NewScanner(stream)
	scanner.Buffer(make([]byte, 0, 64*1024), 1<<20)
	for scanner.Scan() {
		lines = append(lines, scanner.Text())
	}
	if err := scanner.Err(); err != nil {
		return nil, false, sanitizeK8sErr(err)
	}

	// Getting back exactly as many lines as requested is indistinguishable
	// from "there were more before the server-side tail cut them off" —
	// flag it rather than claim completeness we can't verify.
	truncated := int64(len(lines)) >= tail
	return mustMarshal(getLogsResult{Lines: lines}), truncated, nil
}

// explainLogsError turns a failed log read into a plain sentence saying why
// there is no log, from the pod's own status: the pod or container does not
// exist, the container has not started, or there is no previous container.
// The API server's text for these (a 400 such as `container "x" in pod "y"
// is waiting to start: ContainerCreating`) would otherwise reach the caller
// only as the generic sanitized "request failed". Anything it cannot explain
// falls back to sanitizeK8sErr.
func (e *ToolExecutor) explainLogsError(ctx context.Context, args getLogsArgs, streamErr error) error {
	pod, found, lookupErr := e.podForLogs(ctx, args.Namespace, args.Pod)
	if lookupErr != nil {
		return sanitizeK8sErr(streamErr)
	}
	if !found {
		return notFoundError("Pod", args.Namespace, args.Pod)
	}
	container := args.Container
	if container == "" {
		if len(pod.Spec.Containers) != 1 {
			names := make([]string, 0, len(pod.Spec.Containers))
			for _, c := range pod.Spec.Containers {
				names = append(names, c.Name)
			}
			return fmt.Errorf("pod %s/%s has %d containers (%s); name the container to read", args.Namespace, args.Pod, len(names), strings.Join(names, ", "))
		}
		container = pod.Spec.Containers[0].Name
	}
	var status *corev1.ContainerStatus
	declared := false
	for _, list := range [][]corev1.ContainerStatus{pod.Status.InitContainerStatuses, pod.Status.ContainerStatuses, pod.Status.EphemeralContainerStatuses} {
		for i := range list {
			if list[i].Name == container {
				status = &list[i]
			}
		}
	}
	for _, c := range append(append([]corev1.Container{}, pod.Spec.InitContainers...), pod.Spec.Containers...) {
		if c.Name == container {
			declared = true
		}
	}
	for _, c := range pod.Spec.EphemeralContainers {
		if c.Name == container {
			declared = true
		}
	}
	switch {
	case !declared && status == nil:
		return fmt.Errorf("container %s not found in pod %s/%s", container, args.Namespace, args.Pod)
	case args.Previous && (status == nil || status.RestartCount == 0):
		return fmt.Errorf("container %s has not restarted, so there is no previous container's log", container)
	case !args.Previous && status == nil:
		return fmt.Errorf("container %s in pod %s/%s has not started yet (pod is %s), so it has no logs", container, args.Namespace, args.Pod, podPhaseWord(pod))
	case !args.Previous && status.State.Waiting != nil && status.State.Running == nil && status.State.Terminated == nil && status.LastTerminationState.Terminated == nil:
		reason := status.State.Waiting.Reason
		if reason == "" {
			reason = "waiting"
		}
		return fmt.Errorf("container %s in pod %s/%s has not started yet (%s), so it has no logs", container, args.Namespace, args.Pod, reason)
	}
	return sanitizeK8sErr(streamErr)
}

// podForLogs reads the pod from the object cache when it holds it, and with
// one named get otherwise (the cache may not have caught up with a new pod).
func (e *ToolExecutor) podForLogs(ctx context.Context, ns, name string) (*corev1.Pod, bool, error) {
	if e.objects != nil {
		if p, ok, err := e.objects.Pod(ns, name); err == nil && ok {
			return p, true, nil
		}
	}
	p, err := e.typed.CoreV1().Pods(ns).Get(ctx, name, metav1.GetOptions{})
	if apierrors.IsNotFound(err) {
		return nil, false, nil
	}
	if err != nil {
		return nil, false, err
	}
	return p, true, nil
}

func podPhaseWord(pod *corev1.Pod) string {
	if pod.Status.Phase == "" {
		return "Pending"
	}
	return string(pod.Status.Phase)
}
